<?php
namespace App\Features\Post\Controllers;
use App\Http\Controllers\Controller;use App\Features\Post\Models\Post;use App\Features\Post\Services\PostService;use App\Features\Post\Services\PostExcelService;use App\Features\Ai\Contracts\AiClientInterface;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;use Inertia\Inertia;
class PostController extends Controller { public function index(Request $r){$posts=Post::where('user_id',$r->user()->id)->latest()->paginate(10)->withQueryString();return Inertia::render('Post/Index',['posts'=>$posts,'stats'=>['total'=>Post::where('user_id',$r->user()->id)->count(),'published'=>Post::where('user_id',$r->user()->id)->where('is_published',true)->count(),'draft'=>Post::where('user_id',$r->user()->id)->where('is_published',false)->count()],'categories'=>\App\Features\Post\Enums\PostCategory::values()]);} public function store(Request $r,PostService $s){$data=$this->validated($r);$s->create($r->user()->id,$data);return back()->with('success','Artikel berhasil dibuat.');} public function show(Post $post){$this->authorize('view',$post);return Inertia::render('Post/Show',['post'=>$post]);} public function update(Request $r,Post $post,PostService $s){$this->authorize('update',$post);$s->update($post,$this->validated($r));return back()->with('success','Artikel diperbarui.');} public function destroy(Post $post,PostService $s){$this->authorize('delete',$post);if($post->cover_image_path)Storage::disk('public')->delete($post->cover_image_path);$s->delete($post);return redirect()->route('posts.index')->with('success','Artikel dihapus.');} public function publish(Post $post,PostService $s){$this->authorize('update',$post);$s->togglePublish($post);return back()->with('success','Status publikasi diperbarui.');} public function cover(Request $r,Post $post){$this->authorize('update',$post);$r->validate(['cover'=>'required|image|mimes:jpg,jpeg,png,webp|max:5120']);if($post->cover_image_path)Storage::disk('public')->delete($post->cover_image_path);$post->cover_image_path=$r->file('cover')->store('covers','public');$post->save();return back()->with('success','Cover berhasil diunggah.');} public function deleteCover(Post $post){$this->authorize('update',$post);if($post->cover_image_path)Storage::disk('public')->delete($post->cover_image_path);$post->update(['cover_image_path'=>null]);return back()->with('success','Cover dihapus.');} public function export(Request $r,PostExcelService $excel){$path=$excel->export(Post::where('user_id',$r->user()->id)->get());return response()->download($path,'artikel-saya.xlsx')->deleteFileAfterSend();} public function import(Request $r,PostExcelService $excel){$r->validate(['file'=>'required|file|mimes:xlsx,xls|max:10240']);$count=$excel->import($r->file('file')->getRealPath(),$r->user()->id);return back()->with('success',"{$count} artikel berhasil diimpor.");} public function aiGenerate(Request $r,AiClientInterface $ai){$data=$r->validate(['prompt'=>'required|string|min:5|max:1000','count'=>'required|integer|min:1|max:5']);return response()->json(['articles'=>$ai->generate($data['prompt'],$data['count'])]);} public function aiSave(Request $r,PostService $s){$data=$r->validate(['articles'=>'required|array|min:1|max:5','articles.*.title'=>'required|string|max:255','articles.*.category'=>'required|in:'.implode(',',\App\Features\Post\Enums\PostCategory::values()),'articles.*.excerpt'=>'nullable|string','articles.*.content'=>'required|string']);foreach($data['articles'] as $article)$s->create($r->user()->id,$article);return back()->with('success','Draft hasil AI berhasil disimpan.');} private function validated(Request $r):array{return $r->validate(['title'=>'required|string|max:255','category'=>'required|in:'.implode(',',\App\Features\Post\Enums\PostCategory::values()),'excerpt'=>'nullable|string|max:1000','content'=>'required|string','is_published'=>'sometimes|boolean']);} }
